INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "张建武", "aliases": ["張建武"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋冀州刺史。941年十二月庚子与其他将领攻取赵州。生卒年未载。", "biography": null, "status": "draft", "id": "7765b3b9-ef54-547e-88e3-6127aca4d1db"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "郭彦钦", "aliases": ["郭彥欽"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周庆州刺史。《资治通鉴》记其为索取贿赂而侵扰野鸡族，导致当地反抗及商旅遭抢掠。生卒年未载。", "biography": null, "status": "draft", "id": "a5916bd2-ffb5-5cb1-8194-496b8dad0993"}, {"name": "郭元昭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "浚仪人，曾任解州刺史。此前因与榷盐使李温玉不和而诬报其叛乱，牵连魏仁浦。953年返京后由魏仁浦奏请任庆州刺史。《宋史》同案写郑元昭且纪时有别，保存异说，不直接改姓或另造同案人物。生卒年未载。", "biography": null, "status": "draft", "id": "e1d77274-7474-52ad-ab8d-8a67e6932967"}, {"name": "李温玉", "aliases": ["李溫玉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "榷盐使，魏仁浦的岳父。后汉乾祐年间因儿子在李守贞据守的河中而遭郭元昭诬报、拘禁，郭威知道冤情后予以释放。《宋史》补称其管理安邑、解县两池，生卒年未载。", "biography": null, "status": "draft", "id": "bfdf1296-2c14-5d0b-9610-63aa7b7d4c28"}, {"name": "魏仁浦", "aliases": ["魏仁溥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字道济，卫州汲人。后晋末任枢密院小吏，随众被迁往契丹后逃归。947年在巩县迎见刘知远，因熟知军队人数与旧制受到郭威信任。生卒年尚未录入。", "biography": null, "status": "draft", "id": "c2e87754-6e6a-56db-b3e1-45835b2bff92"}, {"name": "魏仁涤", "aliases": ["魏仁滌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏仁浦之弟。953年郭元昭返京途中在洛阳向他诉说恐惧，他认为其兄不会以私人恩怨损害公事。《宋史》同案也记这番回应，生卒年未载。", "biography": null, "status": "draft", "id": "c18078f8-b33e-5415-aa3b-69ee7364676a"}, {"name": "王仁镐", "aliases": ["王仁鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：王仁镐，供奉官、报告所指称制执行者。", "biography": null, "status": "draft", "id": "3b630a2d-5a16-50b8-b441-93eebb35e76f"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "冯延巳", "aliases": ["馮延巳", "冯延己", "馮延己", "冯延已"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，曾任驾部郎中、齐王元帅府常书记。《资治通鉴》本段作冯延己及延已，《新五代史》作冯延巳；据同一南唐政局、陈觉及常梦锡等对应关系校核为同人，展示采用冯延巳，原文异体保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "0b3ed4d7-1a4c-50a5-ad65-aee4b82089ba"}, {"name": "周行逢", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军副使。951年与王逵率修府士兵逃回朗州。《宋史》记为朗州武陵人，早年因犯法被编入军队，凭骁勇升任军官。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1bc0f62b-e1c1-5468-a9db-2d2d5444ab22"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "张亻放（楚军指挥使）", "aliases": ["张仿", "張仿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国诸军指挥使。951年与王逵、周行逢、何敬真共同处理朗州军府事务。电子底本姓名末字写作“亻放”，字形待核，暂不与其他记载中的张仿合并。生卒年未载。", "biography": null, "status": "draft", "id": "b66c1113-4e1b-5c98-9a58-2258c1bad288"}, {"name": "常思", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉昭义节度使。948年讨伐李守贞等三镇时曾驻潼关，后来与郭威、白文珂、刘词分三路进攻河中。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "1d3a1e89-5826-52d4-ba66-55dbc3d91e22"}, {"name": "毋昭裔", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：毋昭裔，龙门人、原御史中丞、获任宰辅者。", "biography": null, "status": "draft", "id": "4d43c16a-22c8-593d-ba83-347e273efd9a"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "张藏英", "aliases": ["張藏英"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "涿州范阳人，契丹军使，兼任榷盐制置等职。953年率军士、亲属、盐户等归附后周。《通鉴》电子本户台与旧史卢台、宋传盧䑓写法有别，按同人同役保留校核说明。生卒年留待后续逐段补录。", "biography": null, "status": "draft", "id": "f4a79754-77c7-514a-a927-bc9d261e9a40"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "李愚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷262光化三年条所见人物：李愚。", "biography": null, "status": "draft", "id": "0d7b36cf-a698-5a6e-a565-1dc4e5d6c11d"}, {"name": "田敏", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周尚书左丞。951年二月奉命出使契丹。《旧五代史》也记录他充契丹国信使。生卒年尚未录入。", "biography": null, "status": "draft", "id": "73deef56-8053-59f4-8081-4746e12611ce"}, {"name": "郑珓", "aliases": ["鄭珓"], "era": "五代十国", "birth_year": null, "death_year": 953, "description": "湖南指挥使。953年王逵攻入朗州时被杀。生年未载。", "biography": null, "status": "draft", "id": "056855b4-cb3e-5b7d-bf1c-d3aaef37d8b8"}, {"name": "刘言", "aliases": ["劉言"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吉州庐陵人，楚国辰州刺史。951年王逵、周行逢等欲迎他到朗州任副使，他单骑前往，众人废去马光惠后推他为权武平留后。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b32e335e-b386-5ab9-a996-bb31d55c6787"}, {"name": "王殷（后汉后周将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州籍将领。950年以侍卫步军都指挥使身份奉命驻澶州防备契丹，后来参与后周建国。《旧五代史》记他自称出生在魏州开元寺，籍贯与出生地分开。与晚唐后梁同名王殷分开建档，生卒年本批未录。", "biography": null, "status": "draft", "id": "4b85115a-7337-546f-af4c-9f6bd20f13c6"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

